using System.Collections.Generic;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea.RunModifiers;

[CreateAssetMenu(fileName = "RestlessJourneyRunModifier", menuName = "Data/RunModifiers/RestlessJourneyRunModifier", order = 0)]
public class RestlessJourneyRunModifier : HeartModificationRunModifier
{
	[SerializeField]
	private RecoverAllHeartsReward recoverAllHeartsReward;

	public override void Initialize()
	{
		ReferenceSingleton<RunModifiersManager>.Instance.RestlessJourneyRunModifier = this;
		base.Initialize();
	}

	public Reward[] GetBattleModifiedRewards(Reward[] nonModifiedRewards)
	{
		List<Reward> list = nonModifiedRewards.DuplicateAsList();
		if (!list.Contains(recoverAllHeartsReward))
		{
			return nonModifiedRewards;
		}
		list.Remove(recoverAllHeartsReward);
		return list.ToArray();
	}

	public override string GetLocalizedDescription()
	{
		return Smart.Format(base.localizedDescription, runModifierVariableAmount);
	}
}
